// Enabled only by a local imageTrace=1 inspection. No UI or production telemetry.
export function traceGalleryImages(dialog) {
  const report = (kind, data) => console.info(`[gallery-images] ${JSON.stringify({kind,at:Math.round(performance.now()),...data})}`);
  const resources = new PerformanceObserver(list => {
    for (const entry of list.getEntries()) if (/view-covers\/|view-assets\/|exhibition-images\/|\/shares\/[^/]+\/assets\//.test(entry.name)) {
      report('resource', { file:entry.name.split('/').pop(),start:Math.round(entry.startTime),duration:Math.round(entry.duration),bytes:entry.transferSize });
    }
  });
  resources.observe({ type:'resource',buffered:true });
  let panel = null;
  const mutation = new MutationObserver(() => {
    const next = dialog.querySelector('.museum-directory');
    if (next === panel) return;
    panel = next;
    if (next) requestAnimationFrame(() => {
      const images = [...next.querySelectorAll('img')];
      report('panel-first-frame', { cards:next.querySelectorAll('.museum-exhibition-item').length,images:images.length,ready:images.filter(image=>image.complete&&image.naturalWidth>0).length });
    });
  });
  mutation.observe(dialog, { childList:true,subtree:true });
  report('mounted', {});
  return () => { resources.disconnect();mutation.disconnect(); };
}
